{
  "findings": [
    {
      "ref": "[R271]",
      "area": "age_gating",
      "claim": "A parent reports that the app does not allow control over which holiday themes are shown, and they wish for parental controls to hide certain themes.",
      "stance": "risk",
      "quote": "I wish it was mindful on what families do and do not celebrate in terms of holidays. I hope that in the near future it allows parents the opportunity to control which holiday themes they want to expose their child to (or withhold) depending on the family’s preferences and values."
    },
    {
      "ref": "[R303]",
      "area": "contact",
      "claim": "A parent reports that the app includes a voice prompt saying 'oops! Ask a grown-up to check your Internet' that cannot be turned off, which may be concerning for children with autism.",
      "stance": "risk",
      "quote": "It would be nice if you could have an option, especially for users with autism where you can turn that voice prompt to check the Internet off and the pro could be something like a text Bubble or picture or something of that nature."
    },
    {
      "ref": "[R280]",
      "area": "data",
      "claim": "A parent reports that the app is tracking kids' information and warns other parents to beware.",
      "stance": "risk",
      "quote": "It’s tracking your kids, parents bewareeeee!!!!! shut them down, shut them down, shut them down I wish I could give this app zero stars we wewhoop busted busted!!!!!!!!!!!!!!!!): they’re just gathering all your kids informationD: but anyways, it was good for a little bit"
    },
    {
      "ref": "[R291]",
      "area": "age_gating",
      "claim": "A parent reports that the app does not have content for third, fourth, or fifth grade, meaning older children cannot access appropriate material.",
